'use strict'

// Regenerates electron/db/searchFields.js from src/utils/searchFields.js.
//
// The registry has to exist in both module systems (see the header of either
// file). Rather than maintain two copies by hand — which is how the rating
// category list ended up duplicated six ways — the CommonJS side is generated by
// mechanically rewriting `export const` to `const` and appending a
// module.exports block.
//
// Run via `npm run sync:search-fields`. tests/search-fields.test.js fails if the
// checked-in mirror does not match what this would produce, so a forgotten
// re-run is caught by the suite rather than at runtime.

const fs = require('fs')
const path = require('path')

const ROOT = path.join(__dirname, '..')
const SOURCE = path.join(ROOT, 'src', 'utils', 'searchFields.js')
const TARGET = path.join(ROOT, 'electron', 'db', 'searchFields.js')

const HEADER = `'use strict'

// ── Searchable fields (CommonJS mirror) ─────────────────────────────────────
//
// GENERATED from src/utils/searchFields.js by scripts/sync-search-fields.js.
// Do not edit by hand — edit the ESM file and re-run \`npm run sync:search-fields\`.
//
// It exists because main is CommonJS and the renderer is an ESM bundle, so the
// two cannot share a module (same reason electron/db/ratingCategories.js is
// mirrored by src/utils/ratingCategories.js). tests/search-fields.test.js
// asserts the two stay identical, so a stale mirror fails the suite rather than
// silently making Browse search different columns from Library search.

`

function generate() {
  const source = fs.readFileSync(SOURCE, 'utf8').replace(/\r\n/g, '\n')
  const names = [...source.matchAll(/^export const (\w+)/gm)].map((m) => m[1])
  if (names.length === 0) {
    throw new Error('No `export const` declarations found in searchFields.js')
  }

  let body = source.replace(/^export const /gm, 'const ')
  // Drop the ESM file's own doc comment; HEADER replaces it.
  const start = body.indexOf('const SEARCH_FIELDS')
  if (start === -1) throw new Error('SEARCH_FIELDS declaration not found')
  body = body.slice(start)

  const exports = `module.exports = {\n${names.map((n) => `  ${n},\n`).join('')}}\n`
  // Normalise to LF *before* converting, or any CRLF that sneaks in from the
  // header or the source produces \r\r\n -- which survives a naive
  // .replace(/\r\n/g,'\n') in the test and reads as a baffling mismatch.
  return `${HEADER}${body.replace(/\n+$/, '')}\n\n${exports}`
    .replace(/\r\n/g, '\n')
    .replace(/\n/g, '\r\n')
}

if (require.main === module) {
  fs.writeFileSync(TARGET, generate(), 'utf8')
  console.log(`Wrote ${path.relative(ROOT, TARGET)}`)
}

module.exports = { generate, SOURCE, TARGET }
